import { useCallback, useEffect, useState } from "react";
import { ChevronDown, ChevronRight, File, Folder, FolderOpen, GitBranch, RefreshCw } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import { ListDirectory, ReadDocument, SaveDocument } from "../../../wailsjs/go/controllers/Files";
import DocumentEditor, { ConflictDiff } from "../documents/DocumentEditor";
import { fileLanguage } from "../../lib/fileLanguage";
import { useT } from "../../lib/i18n";

type Entry = { name: string; isDir: boolean; size?: number; blocked?: boolean; blockReason?: string };
type Doc = { content: string; revision: string; readOnly: boolean; bom: boolean; eol: string; encoding: string };

// The workspace file browser + editor panel that sits next to the terminal.
export default function WorkspaceNavigator({ projectName }: { projectName: string }) {
  const t = useT();
  const [tab, setTab] = useState<"files" | "git">("files");
  const [path, setPath] = useState("");
  const [entries, setEntries] = useState<Entry[]>([]);
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [doc, setDoc] = useState<Doc | null>(null);
  const [docPath, setDocPath] = useState("");
  const [dirty, setDirty] = useState(false);
  const [conflict, setConflict] = useState<{ original: string; mine: string } | null>(null);
  const [loading, setLoading] = useState(false);

  const refresh = useCallback(async (dirPath: string) => {
    setLoading(true);
    try {
      const result = await ListDirectory("project", projectName, dirPath, "");
      setEntries((result as any)?.entries ?? []);
      setPath(dirPath);
    } catch { /* pre-startup */ } finally {
      setLoading(false);
    }
  }, [projectName]);

  useEffect(() => {
    if (tab === "files" && projectName) {
      void refresh("");
    }
  }, [tab, projectName, refresh]);

  const openDoc = useCallback(async (filePath: string) => {
    try {
      const result = await ReadDocument("project", projectName, filePath);
      const d = result as any;
      if (d?.encoding === "binary" || d?.readOnly) {
        setDoc({ content: "", revision: d?.revision ?? "", readOnly: true, bom: d?.bom, eol: d?.eol, encoding: d?.encoding });
        setDocPath(filePath);
        setDirty(false);
        setConflict(null);
        return;
      }
      setDoc({ content: d?.content ?? "", revision: d?.revision ?? "", readOnly: false, bom: d?.bom, eol: d?.eol, encoding: "utf-8" });
      setDocPath(filePath);
      setDirty(false);
      setConflict(null);
    } catch { /* not found */ }
  }, [projectName]);

  const save = useCallback(async () => {
    if (!doc || !docPath || doc.readOnly || !dirty) return;
    try {
      const [result, newRev] = await SaveDocument("project", projectName, docPath, doc.content, doc.revision);
      if (result === "ok") {
        setDoc((d) => (d ? { ...d, revision: newRev } : d));
        setDirty(false);
        setConflict(null);
      } else if (result === "conflict") {
        // Reload the disk version for the diff view.
        const fresh = await ReadDocument("project", projectName, docPath);
        setConflict({ original: (fresh as any)?.content ?? "", mine: doc.content });
      }
    } catch { /* save failed */ }
  }, [doc, docPath, projectName, dirty]);

  // Ctrl+S handler.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "s" && docPath) {
        e.preventDefault();
        void save();
      }
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [save, docPath]);

  const toggleDir = (dirPath: string) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(dirPath)) {
        next.delete(dirPath);
      } else {
        next.add(dirPath);
      }
      return next;
    });
  };

  const renderDir = (_dirPath: string, _depth: number): React.ReactNode[] => {
    return [];
  };

  return (
    <div className="flex h-full flex-col">
      {/* Tab bar */}
      <div className="flex border-b border-white/10 px-1 text-xs">
        <button
          type="button"
          onClick={() => setTab("files")}
          className={`px-3 py-1.5 ${tab === "files" ? "border-b-2 border-accent text-white" : "text-white/50 hover:text-white/80"}`}
        >
          {t("workspace.files")}
        </button>
        <button
          type="button"
          onClick={() => setTab("git")}
          className={`px-3 py-1.5 ${tab === "git" ? "border-b-2 border-accent text-white" : "text-white/50 hover:text-white/80"}`}
        >
          {t("workspace.git")}
        </button>
      </div>

      {tab === "files" ? (
        <div className="flex min-h-0 flex-1">
          {/* File list */}
          <div className="w-full min-w-0 overflow-y-auto border-r border-white/10 p-1" style={{ maxWidth: "280px" }}>
            {loading && <p className="px-2 py-1 text-xs text-white/40">{t("common.loading")}</p>}
            {entries.map((entry) => {
              const childPath = path ? `${path}/${entry.name}` : entry.name;
              return (
                <button
                  key={entry.name}
                  type="button"
                  disabled={entry.blocked}
                  onClick={() => {
                    if (entry.isDir) toggleDir(childPath);
                    else void openDoc(childPath);
                  }}
                  className={`flex w-full items-center gap-1.5 rounded px-2 py-1 text-left text-xs ${
                    entry.blocked ? "text-white/20" : "text-white/70 hover:bg-white/5"
                  } ${docPath === childPath ? "bg-white/10 text-white" : ""}`}
                  style={{ paddingLeft: `${8 + (path ? path.split("/").length * 8 : 0)}px` }}
                >
                  {entry.isDir ? (
                    expanded.has(childPath) ? <FolderOpen className="h-3.5 w-3.5 text-accent2" /> : <Folder className="h-3.5 w-3.5 text-accent2" />
                  ) : (
                    <File className="h-3.5 w-3.5 text-white/40" />
                  )}
                  <span className="truncate">{entry.name}</span>
                  {entry.blocked && <span className="text-[9px] text-red-300/50">({entry.blockReason})</span>}
                </button>
              );
            })}
          </div>

          {/* Editor */}
          <div className="relative min-w-0 flex-1">
            {doc ? (
              <>
                <div className="flex items-center justify-between border-b border-white/10 px-3 py-1 text-xs">
                  <span className="truncate font-mono text-white/70">{docPath}</span>
                  <div className="flex items-center gap-2">
                    {doc.readOnly && <span className="text-amber-300/70">{t("workspace.readOnly")}</span>}
                    {dirty && <span className="text-accent2">●</span>}
                    <button
                      type="button"
                      onClick={() => void save()}
                      disabled={!dirty || doc.readOnly}
                      className="rounded border border-white/10 px-2 py-0.5 text-white/70 hover:bg-white/10 disabled:opacity-40"
                    >
                      {t("workspace.save")}
                    </button>
                  </div>
                </div>
                <div className="h-[calc(100%-28px)]">
                  {conflict ? (
                    <ConflictDiff original={conflict.original} modified={conflict.mine} language={fileLanguage(docPath)} />
                  ) : (
                    <DocumentEditor
                      value={doc.content}
                      language={fileLanguage(docPath)}
                      readOnly={doc.readOnly}
                      onChange={(v) => {
                        setDoc((d) => (d ? { ...d, content: v } : d));
                        setDirty(true);
                      }}
                    />
                  )}
                </div>
              </>
            ) : (
              <div className="flex h-full items-center justify-center text-xs text-white/30">
                {t("workspace.selectFile")}
              </div>
            )}
          </div>
        </div>
      ) : (
        <GitPanel projectName={projectName} />
      )}
    </div>
  );
}

// --- Git Panel ----------------------------------------------------------------

type GitFile = { path: string; staged: boolean; unstaged: boolean; untracked: boolean };
type GitStatus = { branch: string; upstream?: string; ahead: number; behind: number; files: GitFile[] };

function GitPanel({ projectName }: { projectName: string }) {
  const t = useT();
  const [status, setStatus] = useState<GitStatus | null>(null);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);

  const refresh = useCallback(async () => {
    try {
      const s = await (await import("../../../wailsjs/go/controllers/Git")).GetSourceControlStatus(projectName);
      setStatus(s as any);
    } catch { /* not a repo */ }
  }, [projectName]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const stage = async (paths: string[]) => {
    setBusy(true);
    const Git = await import("../../../wailsjs/go/controllers/Git");
    await Git.StartSourceControlStage(projectName, paths);
    setBusy(false);
    void refresh();
  };

  const unstage = async (paths: string[]) => {
    setBusy(true);
    const Git = await import("../../../wailsjs/go/controllers/Git");
    await Git.StartSourceControlUnstage(projectName, paths);
    setBusy(false);
    void refresh();
  };

  const commit = async () => {
    if (!message.trim()) return;
    setBusy(true);
    const Git = await import("../../../wailsjs/go/controllers/Git");
    await Git.StartSourceControlCommit(projectName, message);
    setMessage("");
    setBusy(false);
    void refresh();
  };

  const push = async () => {
    setBusy(true);
    const Git = await import("../../../wailsjs/go/controllers/Git");
    await Git.StartSourceControlPush(projectName);
    setBusy(false);
    void refresh();
  };

  if (!status) {
    return <div className="flex h-full items-center justify-center text-xs text-white/30">{t("workspace.git.notRepo")}</div>;
  }

  const staged = status.files.filter((f) => f.staged);
  const unstaged = status.files.filter((f) => !f.staged);

  return (
    <div className="flex h-full flex-col gap-2 overflow-y-auto p-2 text-xs">
      <div className="flex items-center gap-2 border-b border-white/10 pb-2">
        <GitBranch className="h-3.5 w-3.5 text-accent2" />
        <span className="font-mono text-white/80">{status.branch}</span>
        {status.upstream && (
          <span className="text-white/40">
            {status.ahead > 0 && `↑${status.ahead}`}
            {status.behind > 0 && ` ↓${status.behind}`}
            {" "}{status.upstream}
          </span>
        )}
      </div>

      {/* Staged */}
      <div>
        <div className="mb-1 flex items-center justify-between">
          <span className="font-medium text-white/60">{t("workspace.git.staged")} ({staged.length})</span>
          {staged.length > 0 && (
            <button type="button" onClick={() => void unstage(staged.map((f) => f.path))} className="text-white/40 hover:text-white">
              {t("workspace.git.unstageAll")}
            </button>
          )}
        </div>
        {staged.map((f) => (
          <div key={f.path} className="flex items-center gap-1 py-0.5">
            <span className="min-w-4 text-center text-emerald-400">+</span>
            <span className="flex-1 truncate text-white/70">{f.path}</span>
            <button type="button" onClick={() => void unstage([f.path])} className="text-white/30 hover:text-white">−</button>
          </div>
        ))}
      </div>

      {/* Unstaged */}
      <div>
        <div className="mb-1 flex items-center justify-between">
          <span className="font-medium text-white/60">{t("workspace.git.changes")} ({unstaged.length})</span>
          {unstaged.length > 0 && (
            <button type="button" onClick={() => void stage(unstaged.map((f) => f.path))} className="text-white/40 hover:text-white">
              {t("workspace.git.stageAll")}
            </button>
          )}
        </div>
        {unstaged.map((f) => (
          <div key={f.path} className="flex items-center gap-1 py-0.5">
            <span className={`min-w-4 text-center ${f.untracked ? "text-red-400" : "text-amber-400"}`}>
              {f.untracked ? "?" : "M"}
            </span>
            <span className="flex-1 truncate text-white/70">{f.path}</span>
            <button type="button" onClick={() => void stage([f.path])} className="text-white/30 hover:text-white">+</button>
          </div>
        ))}
      </div>

      {/* Commit + Push */}
      <div className="mt-auto space-y-2 border-t border-white/10 pt-2">
        <textarea
          className="input w-full resize-none text-xs"
          rows={2}
          placeholder={t("workspace.git.commitMessage")}
          value={message}
          onChange={(e) => setMessage(e.target.value)}
        />
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => void commit()}
            disabled={!message.trim() || staged.length === 0 || busy}
            className="flex-1 rounded bg-accent px-3 py-1.5 text-xs font-medium text-white disabled:opacity-40"
          >
            {t("workspace.git.commit")}
          </button>
          <button
            type="button"
            onClick={() => void push()}
            disabled={busy}
            className="flex-1 rounded border border-white/15 bg-white/5 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10 disabled:opacity-40"
          >
            {t("workspace.git.push")}
          </button>
        </div>
      </div>
    </div>
  );
}
